import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import matter from 'gray-matter';
import { marked } from 'marked';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.join(__dirname, '..');

const POSTS_DIR = path.join(rootDir, 'content/blog');
const PROJECTS_DIR = path.join(rootDir, 'content/projects');
const OUTPUT_DIR = path.join(rootDir, 'lib/server');
const OUTPUT_FILE = path.join(OUTPUT_DIR, 'bundled-content.js');

function ensureDir(dir) {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function readMdxFiles(dir) {
  if (!fs.existsSync(dir)) {
    return [];
  }

  return fs.readdirSync(dir)
    .filter(fileName => fileName.endsWith('.mdx'))
    .map(fileName => {
      const id = fileName.replace(/\.mdx$/, '');
      const fullPath = path.join(dir, fileName);
      const fileContents = fs.readFileSync(fullPath, 'utf8');
      const matterResult = matter(fileContents);

      return {
        id,
        type: dir.includes('blog') ? 'post' : 'project',
        content: matterResult.content,
        processedContent: marked(matterResult.content),
        data: matterResult.data,
      };
    });
}

function main() {
  console.log('Bundling content...');

  ensureDir(OUTPUT_DIR);

  // Read all posts
  const posts = readMdxFiles(POSTS_DIR);
  console.log(`Found ${posts.length} blog posts`);

  // Read all projects
  const projects = readMdxFiles(PROJECTS_DIR);
  console.log(`Found ${projects.length} projects`);

  // Generate the bundle
  const bundleContent = `// This file is auto-generated by scripts/bundle-content.js
// Do not edit manually

export const bundledPosts = ${JSON.stringify(posts, null, 2)};

export const bundledProjects = ${JSON.stringify(projects, null, 2)};

export function getAllPosts() {
  return bundledPosts
    .map(post => ({
      id: post.id,
      slug: \`/blog/\${post.id}\`,
      slugAsParams: post.id,
      content: post.content,
      title: post.data.title || "",
      description: post.data.description || "",
      publishedAt: post.data.publishedAt || "",
      tags: post.data.tags || [],
      keywords: post.data.keywords || "",
      image: post.data.image || "",
      ...post.data,
    }))
    .sort((a, b) => {
      if (a.publishedAt < b.publishedAt) return 1;
      else return -1;
    });
}

export function getPostBySlug(slug) {
  const post = bundledPosts.find(p => p.id === slug);
  if (!post) return null;

  return {
    slug: \`/blog/\${slug}\`,
    slugAsParams: slug,
    content: post.processedContent,
    title: post.data.title || "",
    description: post.data.description || "",
    publishedAt: post.data.publishedAt || "",
    tags: post.data.tags || [],
    keywords: post.data.keywords || "",
    image: post.data.image || "",
    ...post.data,
  };
}

export function getAllProjects() {
  return bundledProjects
    .map(project => ({
      id: project.id,
      slug: \`/projects/\${project.id}\`,
      slugAsParams: project.id,
      content: project.processedContent,
      title: project.data.title || "",
      description: project.data.description || "",
      publishedAt: project.data.publishedAt || "",
      tags: project.data.tags || [],
      keywords: project.data.keywords || "",
      image: project.data.image || "",
      cover: project.data.cover || "",
      link: project.data.link || "",
      ...project.data,
    }))
    .sort((a, b) => {
      if (a.publishedAt < b.publishedAt) return 1;
      else return -1;
    });
}

export function getProjectBySlug(slug) {
  const project = bundledProjects.find(p => p.id === slug);
  if (!project) return null;

  return {
    slug: \`/projects/\${slug}\`,
    slugAsParams: slug,
    content: project.processedContent,
    title: project.data.title || "",
    description: project.data.description || "",
    publishedAt: project.data.publishedAt || "",
    tags: project.data.tags || [],
    keywords: project.data.keywords || "",
    image: project.data.image || "",
    cover: project.data.cover || "",
    link: project.data.link || "",
    ...project.data,
  };
}
`;

  fs.writeFileSync(OUTPUT_FILE, bundleContent);
  console.log(`Content bundled to ${OUTPUT_FILE}`);
}

main();
